(()=>{'use strict';
const DATA_URL='novos-torneios/index.json';
const TEAM_LOGOS={
'ALPHA7':'A7 2.webp','AXS FUSION':'AXS BRANCA.webp','CPT VOX':'cpt vox.webp','E1 SPORTS':'E1.webp',
'FLUXO W7M':'Fluxo 2.webp','INFLUENCE RAGE':'Influence Rage.webp','INTZ':'Intz 1.webp','LOOPS':'Loops 1.webp',
'LOS':'Los.webp','LOUD':'loud 2.webp','LOUD SNICKERS':'loud 2.webp','RUSH GAMING':'Rush.webp','TEAM SOLID':'Team Solid 2.webp',
'FURY UNITED':'https://i.postimg.cc/x8rCzzNm/futd.webp','HAWK GAMING':'https://i.postimg.cc/63y6hk2N/hawk.webp','LYON':'https://i.postimg.cc/XYGTQnxR/inco.webp'
};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase();
const date=v=>{const m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:String(v||'')};
const logo=name=>TEAM_LOGOS[norm(name)]||'escudo.webp';
const shortTeam=name=>({
'FLUXO W7M':'FX','TEAM SOLID':'TS','RUSH GAMING':'RUSH','RISE GAMING':'RISE','INFLUENCE RAGE':'INF',
'FURY UNITED':'FURY','LOUD SNICKERS':'LOUD','AXS FUSION':'AXS','HAWK GAMING':'HAWK','ALPHA7':'A7','CPT VOX':'CPT','AFROGAMES':'AFG','CIVIS':'CTZ','LOOPS':'LPS','SX TET':'SX'
}[norm(name)]||String(name||''));
const rankClass=i=>i===0?'pos-1':i===1?'pos-2':i===2?'pos-3':i===3?'pos-4':'pos-5';
function empty(root,msg){if(root)root.innerHTML=`<div class="home-year-loading">${esc(msg)}</div>`}
function clone(value){try{return JSON.parse(JSON.stringify(value))}catch(_){return value}}
function databaseBase(){return String(window.CFF_CONFIG?.firebase?.databaseURL||'').replace(/\/$/,'')}
async function loadAdminTitles(){
 const base=databaseBase(); if(!base)return [];
 try{const r=await fetch(base+'/adminTitles.json',{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const raw=await r.json();return Object.values(raw||{}).filter(Boolean)}catch(_){return []}
}
function normalizeAdminMvp(event){
 const src=Array.isArray(event?.mvpRanking)?event.mvpRanking:Object.values(event?.mvpRanking||{});
 return src.map((entry,index)=>({position:Number(entry?.position||index+1),player:String(entry?.player||'').trim()})).filter(entry=>entry.position>=1&&entry.position<=5&&entry.player).sort((a,b)=>a.position-b.position);
}
function mergeAdminTitles(baseData,adminEvents){
 const data=clone(baseData)||{};
 data.events=Array.isArray(data.events)?data.events:[];
 data.titleRanking=Array.isArray(data.titleRanking)?data.titleRanking:[];
 data.mvpRanking=Array.isArray(data.mvpRanking)?data.mvpRanking:[];
 const staticIds=new Set(data.events.map(e=>String(e?.id||'')).filter(Boolean));
 const titles=new Map(data.titleRanking.map(r=>[norm(r.team),{...r,first:Number(r.first||0),second:Number(r.second||0),third:Number(r.third||0),total:Number(r.total||0)}]));
 const mvps=new Map(data.mvpRanking.map(r=>[norm(r.player),{...r,first:Number(r.first||0),second:Number(r.second||0),third:Number(r.third||0),fourth:Number(r.fourth||0),fifth:Number(r.fifth||0),total:Number(r.total||0)}]));
 let added=0;
 (adminEvents||[]).forEach(raw=>{
   const id=String(raw?.id||'').trim(); if(!id||staticIds.has(id))return;
   const ranking=normalizeAdminMvp(raw);
   const event={id,name:String(raw?.name||id),date:String(raw?.date||''),winner:String(raw?.winner||''),runnerUp:String(raw?.runnerUp||''),third:String(raw?.third||''),mvp:ranking[0]?.player?[ranking[0].player]:[],mvpRanking:ranking,source:'admin'};
   if(!event.winner||!event.runnerUp||!event.third)return;
   data.events.push(event); staticIds.add(id); added++;
   [[event.winner,'first'],[event.runnerUp,'second'],[event.third,'third']].forEach(([team,key])=>{
     const n=norm(team); if(!n)return; const row=titles.get(n)||{team,first:0,second:0,third:0,total:0}; row[key]=Number(row[key]||0)+1; row.total=Number(row.first||0)+Number(row.second||0)+Number(row.third||0); titles.set(n,row);
   });
   ranking.forEach(entry=>{
     const n=norm(entry.player); if(!n)return; const row=mvps.get(n)||{player:entry.player,flag:'br',first:0,second:0,third:0,fourth:0,fifth:0,total:0};
     const key=['','first','second','third','fourth','fifth'][entry.position]; row[key]=Number(row[key]||0)+1; row.total=Number(row.first||0)+Number(row.second||0)+Number(row.third||0)+Number(row.fourth||0)+Number(row.fifth||0); mvps.set(n,row);
   });
 });
 data.titleRanking=[...titles.values()].sort((a,b)=>Number(b.first||0)-Number(a.first||0)||Number(b.second||0)-Number(a.second||0)||Number(b.third||0)-Number(a.third||0)||Number(b.total||0)-Number(a.total||0)||String(a.team||'').localeCompare(String(b.team||''),'pt-BR'));
 data.mvpRanking=[...mvps.values()].map(r=>({...r,total:Number(r.first||0)+Number(r.second||0)+Number(r.third||0)+Number(r.fourth||0)+Number(r.fifth||0)})).sort((a,b)=>Number(b.first||0)-Number(a.first||0)||Number(b.second||0)-Number(a.second||0)||Number(b.third||0)-Number(a.third||0)||Number(b.fourth||0)-Number(a.fourth||0)||Number(b.fifth||0)-Number(a.fifth||0)||Number(b.total||0)-Number(a.total||0)||String(a.player||'').localeCompare(String(b.player||''),'pt-BR'));
 data.totalEvents=Number(baseData?.totalEvents||data.events.length-added)+added;
 if(added){const newest=data.events.map(e=>String(e?.date||'')).filter(Boolean).sort().pop();if(newest)data.updatedAt=newest}
 return data;
}
function renderChampions(data){
 const root=document.getElementById('home-year-latest-champions'); if(!root)return;
 const events=[...(data?.events||[])].filter(e=>e&&e.winner).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,4);
 if(!events.length)return empty(root,'Nenhum campeão registrado ainda.');
 root.innerHTML=events.map(e=>`<article class="home-latest-champion">
   <img src="${esc(logo(e.winner))}" loading="lazy" decoding="async" onerror="this.src='escudo.webp'" alt="${esc(e.winner||'Equipe')}">
   <div class="home-latest-champion-copy"><span class="home-latest-champion-event">${esc(e.name||'Torneio')}</span><strong>${esc(e.winner||'—')}</strong><small>${esc(date(e.date))}</small></div>
 </article>`).join('');
}
function renderTitles(data){
 const root=document.getElementById('home-year-titles-ranking'); if(!root)return;
 const rows=(data?.titleRanking||[]).slice(0,5);
 const kicker=document.querySelector('#home-year-titles-title')?.previousElementSibling;
 if(kicker&&data?.totalEvents!=null)kicker.textContent=`${Number(data.totalEvents)||0} TORNEIOS REGISTRADOS`;
 if(!rows.length)return empty(root,'Ranking ainda não disponível.');
 root.innerHTML=`<table class="home-year-mini-table"><thead><tr><th>#</th><th>Equipe</th><th class="home-medal-gold">1º</th><th class="home-medal-silver">2º</th><th class="home-medal-bronze">3º</th><th>Total</th></tr></thead><tbody>${rows.map((r,i)=>`<tr>
 <td class="home-rank-cell"><span class="home-year-rank-badge-mini ${rankClass(i)}">${i+1}º</span></td>
 <td class="home-name-cell"><span class="home-year-name-inline"><img src="${esc(logo(r.team))}" loading="lazy" decoding="async" onerror="this.src='escudo.webp'" alt=""><span class="home-year-team-full">${esc(r.team||'—')}</span><span class="home-year-team-short">${esc(shortTeam(r.team)||'—')}</span></span></td>
 <td class="home-medal-gold">${Number(r.first||0)}</td><td class="home-medal-silver">${Number(r.second||0)}</td><td class="home-medal-bronze">${Number(r.third||0)}</td><td class="home-total-cell">${Number(r.total||0)}</td>
 </tr>`).join('')}</tbody></table>`;
}
function renderMvps(data){
 const root=document.getElementById('home-year-mvps-ranking'); if(!root)return;
 const rows=(data?.mvpRanking||[]).slice(0,5);
 if(!rows.length)return empty(root,'Ranking ainda não disponível.');
 root.innerHTML=`<table class="home-year-mini-table"><thead><tr><th>#</th><th>Player</th><th class="home-medal-gold">1º</th><th class="home-medal-silver">2º</th><th class="home-medal-bronze">3º</th><th>Total</th></tr></thead><tbody>${rows.map((r,i)=>`<tr>
 <td class="home-rank-cell"><span class="home-year-rank-badge-mini ${rankClass(i)}">${i+1}º</span></td><td class="home-name-cell">${esc(r.player||'—')}</td>
 <td class="home-medal-gold">${Number(r.first||0)}</td><td class="home-medal-silver">${Number(r.second||0)}</td><td class="home-medal-bronze">${Number(r.third||0)}</td><td class="home-total-cell">${Number(r.total||0)}</td>
 </tr>`).join('')}</tbody></table>`;
}
function renderAnnualMvpTop5(data){
 const root=document.getElementById('ot-year-mvp-content');if(!root)return;
 const rows=data?.mvpRanking||[],events=[...(data?.events||[])].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 const e=v=>typeof window.yearEsc==='function'?window.yearEsc(v):esc(v),d=v=>typeof window.yearDate==='function'?window.yearDate(v):date(v);
 root.innerHTML=`<div class="ot-year-ranking-head"><div><h3>Ranking de MVPs — 2026</h3><p>Classificação anual pelos TOP 1 ao TOP 5 de MVP registrados nos torneios.</p></div><span class="home-year-kicker">${rows.length} jogadores</span></div>
 <div class="ot-year-table-wrap"><table class="ot-year-table ot-year-mvp-table ot-year-premium-table"><thead><tr><th class="ot-year-rank-head">#</th><th>Player</th><th class="ot-year-medal-head gold">1º</th><th class="ot-year-medal-head silver">2º</th><th class="ot-year-medal-head bronze">3º</th><th>4º</th><th>5º</th><th>Total</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="ot-year-rank-cell"><span class="ot-year-rank-badge ${rankClass(i)}">${i+1}º</span></td><td class="ot-year-player-cell"><button type="button" class="ot-year-player-link" data-player="${e(r.player)}">${e(r.player)}</button></td><td class="ot-year-medal-cell gold">${Number(r.first||0)}</td><td class="ot-year-medal-cell silver">${Number(r.second||0)}</td><td class="ot-year-medal-cell bronze">${Number(r.third||0)}</td><td>${Number(r.fourth||0)}</td><td>${Number(r.fifth||0)}</td><td class="ot-year-total-cell"><strong>${Number(r.total||0)}</strong></td></tr>`).join('')}</tbody></table></div>
 <section class="ot-year-mvp-events"><div class="ot-year-ranking-head"><div><h3>MVP por torneio</h3><p>Vencedores individuais registrados em cada evento.</p></div></div><div class="ot-year-mvp-events-grid">${events.map(ev=>`<article class="ot-year-mvp-event"><strong>${e(ev.name)}</strong><span>MVP: ${(ev.mvp||[]).map(e).join(' / ')||'—'}</span><small>${d(ev.date)}</small></article>`).join('')}</div></section>`;
 if(typeof window.bindYearLinks==='function')window.bindYearLinks(root);
}
function installAnnualTop5Patch(){
 let tries=0;const timer=setInterval(()=>{tries++;if(typeof window.renderYearMvp==='function'&&!window.renderYearMvp.__cffTop5){const wrapped=function(data){renderAnnualMvpTop5(data||window.otYear2026Data||{})};wrapped.__cffTop5=true;window.renderYearMvp=wrapped;clearInterval(timer);if(document.getElementById('ot-year-mvp-content')&&window.otYear2026Data)wrapped(window.otYear2026Data)}else if(tries>120)clearInterval(timer)},250);
}
async function load(){
 try{
   const r=await fetch(DATA_URL,{cache:'default'}); if(!r.ok)throw new Error(`HTTP ${r.status}`);
   const manifest=await r.json(),base=manifest?.year2026;
   if(!base)throw new Error('year2026 ausente');
   const adminTitles=await loadAdminTitles();
   const data=mergeAdminTitles(base,adminTitles);
   window.otManifestData={...(window.otManifestData||manifest),...manifest,year2026:data}; window.otYear2026Data=data;
   renderChampions(data); renderTitles(data); renderMvps(data); installAnnualTop5Patch();
 }catch(_){
   empty(document.getElementById('home-year-latest-champions'),'Dados de 2026 indisponíveis.');
   empty(document.getElementById('home-year-titles-ranking'),'Dados de 2026 indisponíveis.');
   empty(document.getElementById('home-year-mvps-ranking'),'Dados de 2026 indisponíveis.');
 }
}
window.openCff2026View=function(view='events'){
 const v=['events','titles','mvp'].includes(view)?view:'events'; window.__cffOt2026PendingView=v;
 if(typeof window.navigate==='function'){window.navigate('outros-torneios');return;}
 location.hash='outros-torneios';
};
window.cffRenderHomeYear2026=load;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load();
})();
